private string ModuleMarkMau2BodyToHTML()
{
    StringBuilder sb = new StringBuilder();
    int intSTT = 0;
    string strCellStyle = " style='" + MODULE_MARK_TD_BORDER + "text-align:center;'";
    string strNameStyle = " style='" + MODULE_MARK_TD_BORDER + "text-align:left;white-space:nowrap;'";
    string strNoteStyle = " style='" + MODULE_MARK_TD_BORDER + "text-align:left;'";

    for (int i = 0; i < gvData.RowCount; i++)
    {
        DataRow drw = gvData.GetDataRow(i);
        if (drw == null)
            continue;

        intSTT++;
        sb.Append("<tr>");
        sb.Append("<td" + strCellStyle + ">" + intSTT.ToString() + "</td>");

        string strFullName = (drw["StudentFirstName"].ToString() + " " + drw["StudentLastName"].ToString()).Trim();
        sb.Append("<td class='cell-name'" + strNameStyle + ">" + strFullName + "</td>");

        sb.Append("<td" + strCellStyle + ">&nbsp;</td>");
        sb.Append("<td" + strCellStyle + ">&nbsp;</td>");
        sb.Append("<td" + strCellStyle + ">&nbsp;</td>");

        sb.Append("<td" + strCellStyle + ">" + ModuleMarkFormatValue(drw["SummaryLearningMark"]) + "</td>");
        sb.Append("<td" + strCellStyle + ">" + ModuleMarkFormatValue(drw["EthicMark"]) + "</td>");
        sb.Append("<td" + strNoteStyle + ">" + ModuleMarkGetRetakeSubjects(drw) + "</td>");

        string strDescription = "&nbsp;";
        if (drw.Table.Columns.Contains("Description") && drw["Description"] != DBNull.Value && drw["Description"].ToString().Trim() != "")
            strDescription = drw["Description"].ToString().Trim();
        sb.Append("<td" + strNoteStyle + ">" + strDescription + "</td>");
        sb.Append("</tr>\r\n");
    }

    return sb.ToString();
}

