private string ModuleMarkFormatIntValue(object objValue)
{
    if (objValue == null || objValue == DBNull.Value || objValue.ToString().Trim() == "")
        return "&nbsp;";
    return objValue.ToString().Trim();
}

private string ModuleMarkGetAbsentSummaryValue(DataTable dtbAbsentSummary, long lngStudentID, string strColumnName)
{
    if (dtbAbsentSummary == null)
        return "&nbsp;";

    DataRow[] rows = dtbAbsentSummary.Select("StudentID = " + lngStudentID.ToString());
    if (rows.Length == 0)
        return "&nbsp;";

    return ModuleMarkFormatIntValue(rows[0][strColumnName]);
}

